using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;
namespace IrisDesktop {
 // Synthetic compatibility probe only. No bridge, game, real journal or profile.
 public static class ManualWoodCompatibilityFixture {
  static readonly ProgressScope Scope=new ProgressScope{environment="development",accountId="synthetic-account",characterId="synthetic-character"};
  static readonly byte[] Entropy=Encoding.UTF8.GetBytes("SANCTUM:IRIS:ErgonProgress:v1:development");
  static string Id(){return Guid.NewGuid().ToString("D");}
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
  static void Case(string name,Action run){run();Console.WriteLine("PASS "+name);}
  static ProgressMutation Goal(string id,string action="altering"){return new ProgressMutation{kind="CreateGoal",scope=Scope,goalId=id,sourcePlanId=Id(),action=action,displayName=action=="altering"?"목재":"합성 검",targetQuantity=action=="altering"?100:4};}
  static string FileAt(string root){return Path.Combine(root,"development","ergon-progress-v1.dpapi");}
  static void Seed(string root,object doc){Directory.CreateDirectory(Path.GetDirectoryName(FileAt(root)));var bytes=Encoding.UTF8.GetBytes(ProgressDomain.Serialize(doc));try{File.WriteAllBytes(FileAt(root),ProtectedData.Protect(bytes,Entropy,DataProtectionScope.CurrentUser));}finally{Array.Clear(bytes,0,bytes.Length);}}
  static string Child(string root){var path=Path.Combine(root,Id().Substring(0,8));Directory.CreateDirectory(path);return path;}
  static ProgressCommitResult Commit(DesktopErgonProgressStore s,ProgressMutation m){return s.Commit(m,s.Load(Scope).revision,Guid.NewGuid());}
  static Dictionary<string,object> Dict(object value){return (Dictionary<string,object>)value;}
  static ProgressDocument Three(){
   var d=ProgressDomain.Empty("development");string goal=Id(),request=Id();
   Action<ProgressMutation> send=m=>{var r=ProgressDomain.Commit(d,m,d.revision,Guid.NewGuid(),1000);Check(r.status=="committed","synthetic baseline");d=r.document;};
   send(Goal(goal,"crafting"));send(new ProgressMutation{kind="BindPreparedRequest",scope=Scope,goalId=goal,requestId=request,action="crafting",displayName="합성 검",craftCount=4,outputPerCraft=1,expectedOutput=4,preparedAt=500,expiresAt=1500});
   send(new ProgressMutation{kind="ObserveNativeTerminal",scope=Scope,goalId=goal,requestId=request,evidence=new NativeTerminalEvidence{scope=Scope,goalId=goal,requestId=request,action="crafting",displayName="합성 검",craftCount=4,outputPerCraft=1,expectedOutput=4,outcome="completed",startedAt=600,observedAt=1000,verifierVersion=1,rowDigest=new string('a',64)}});
   send(new ProgressMutation{kind="ConfirmQuantity",scope=Scope,goalId=goal,requestId=request,quantity=3,source="user-confirmed"});return d;
  }
  public static void ExportGolden(string path){File.WriteAllText(path,ProgressDomain.Serialize(Three()),new UTF8Encoding(false));}
  static void UnreadableWithoutRewrite(string root,object future){Seed(root,future);var before=File.ReadAllBytes(FileAt(root));var loaded=new DesktopErgonProgressStore(root,"development").Load(Scope);Check(loaded.health=="unavailable"&&loaded.view.goals.Length==0,"v1 must fail closed on unsupported future data");Check(before.SequenceEqual(File.ReadAllBytes(FileAt(root))),"reader rewrote unsupported ciphertext");}
  public static void Run(string root){
   Case("D2C01-existing-audit-roundtrip",()=>{var d=Three();var original=ProgressDomain.Canonical(d);ProgressDomain.Validate(d,"development");var p=Child(root);Seed(p,d);var bytes=File.ReadAllBytes(FileAt(p));var v=new DesktopErgonProgressStore(p,"development").Load(Scope);Check(v.health=="ok"&&v.view.goals[0].confirmedQuantity==3&&v.view.goals[0].remainingQuantity==1,"confirmed3 baseline");Check(bytes.SequenceEqual(File.ReadAllBytes(FileAt(p)))&&original==ProgressDomain.Canonical(d),"baseline changed");});
   Case("D2C02-manual-event-not-current-contract",()=>{var p=Child(root);var s=new DesktopErgonProgressStore(p,"development");var g=Id();Check(Commit(s,Goal(g)).status=="committed","wood goal");var before=File.ReadAllBytes(s.FilePath);var r=Commit(s,new ProgressMutation{kind="ConfirmManualWoodReceipt",scope=Scope,goalId=g,requestId=Id(),quantity=35,source="user-confirmed"});Check(r.status=="rejected"&&s.Load(Scope).view.goals[0].confirmedQuantity==0,"unknown mutation accepted");Check(before.SequenceEqual(File.ReadAllBytes(s.FilePath)),"rejected mutation changed current");});
   Case("D2C03-crafting-confirmation-cannot-confirm-processing",()=>{var p=Child(root);var s=new DesktopErgonProgressStore(p,"development");var g=Id();Commit(s,Goal(g));var request=Id();Check(Commit(s,new ProgressMutation{kind="BindPreparedRequest",scope=Scope,goalId=g,requestId=request,action="altering",displayName="목재",preparedAt=500,expiresAt=1500}).status=="committed","altering request");
    Check(Commit(s,new ProgressMutation{kind="ObserveNativeTerminal",scope=Scope,goalId=g,requestId=request,evidence=new NativeTerminalEvidence{scope=Scope,goalId=g,requestId=request,action="altering",displayName="목재",outcome="registered",startedAt=600,observedAt=1000,verifierVersion=1,rowDigest=new string('b',64)}}).status=="committed","synthetic registered evidence");
    var before=File.ReadAllBytes(s.FilePath);Check(Commit(s,new ProgressMutation{kind="ConfirmQuantity",scope=Scope,goalId=g,requestId=request,quantity=35,source="user-confirmed",confirmation=new QuantityAcknowledgement{requestId=request,quantity=35,revision=s.Load(Scope).revision,zero=true,extra=true,correction=true}}).status=="rejected","processing disguised as crafting");Check(before.SequenceEqual(File.ReadAllBytes(s.FilePath)),"crafting bypass changed current");});
   Case("D2C04-unversioned-optional-field-rejected",()=>{var d=Three();var raw=Dict(ProgressDomain.Serializer().DeserializeObject(ProgressDomain.Serialize(d)));raw["manualReceipts"]=new object[0];UnreadableWithoutRewrite(Child(root),raw);});
   Case("D2C05-null-extension-affects-historical-canonical-meaning",()=>{var d=Three();var e=d.auditEvents[0];var raw=Dict(ProgressDomain.Serializer().DeserializeObject(ProgressDomain.Serialize(e.mutation)));Check(ProgressDomain.Hash(ProgressDomain.Canonical(raw))==e.meaningDigest,"baseline digest");raw["manualReceiptId"]=null;Check(ProgressDomain.Hash(ProgressDomain.Canonical(raw))!=e.meaningDigest,"new null field unexpectedly invisible");});
   Case("D2C06-future-event-even-with-correct-digest-is-unreadable",()=>{var d=Three();var wood=Id();var created=ProgressDomain.Commit(d,Goal(wood),d.revision,Guid.NewGuid(),1050);Check(created.status=="committed","additional wood100 goal");d=created.document;var m=new ProgressMutation{kind="ConfirmManualWoodReceipt",scope=Scope,goalId=wood,requestId=Id(),quantity=35,source="user-confirmed"};var id=Id();var e=new ProgressAuditEvent{eventId=id,operationId=id,mutation=m,revision=d.revision+1,recordedAt=1100,previousDigest=d.commitDigest,meaningDigest=ProgressDomain.Hash(ProgressDomain.Canonical(m))};e.digest=ProgressDomain.Hash(ProgressDomain.Canonical(new{e.eventId,e.operationId,e.meaningDigest,e.revision,e.recordedAt,e.previousDigest,e.mutation}));d.auditEvents.Add(e);d.revision=e.revision;d.previousCommitDigest=e.previousDigest;d.commitDigest=e.digest;UnreadableWithoutRewrite(Child(root),d);});
   Case("D2C07-new-schema-not-implicit-migration",()=>{var d=Three();d.schemaVersion=2;UnreadableWithoutRewrite(Child(root),d);});
   Case("D2C08-old-confirmed3-preserved-after-future-read",()=>{var d=Three();var baseline=Child(root);Seed(baseline,d);var hash=ProgressDomain.Hash(Convert.ToBase64String(File.ReadAllBytes(FileAt(baseline))));var future=Dict(ProgressDomain.Serializer().DeserializeObject(ProgressDomain.Serialize(d)));future["manualReceipts"]=new object[0];UnreadableWithoutRewrite(Child(root),future);var view=new DesktopErgonProgressStore(baseline,"development").Load(Scope);Check(view.health=="ok"&&view.view.goals[0].confirmedQuantity==3&&hash==ProgressDomain.Hash(Convert.ToBase64String(File.ReadAllBytes(FileAt(baseline)))),"original confirmed record damaged");});
  }
 }
